int mySqrt(int x) {
  // Largest r with r*r <= x. Binary search on the answer, O(log x).
  int lo = 0, hi = x < 2 ? x : x / 2;      // for x >= 2, sqrt(x) <= x/2
  while (lo < hi) {
    int mid = lo + (hi - lo + 1) / 2;       // round up, otherwise lo = mid loops forever
    if (mid <= x / mid) lo = mid;           // mid*mid <= x, without overflow
    else hi = mid - 1;
  }
  return lo;
}

int findPeakElement(const std::vector<int>& a) {
    int lo = 0, hi = (int)a.size() - 1;
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;      // mid < hi, so a[mid + 1] exists
        if (a[mid] < a[mid + 1]) lo = mid + 1;   // uphill to the right: a peak is in (mid, hi]
        else hi = mid;                           // downhill: a peak is in [lo, mid]
    }
    return lo;
}

int search(const std::vector<int>& a, int target) {
    int lo = 0, hi = (int)a.size() - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (a[mid] == target) return mid;
        if (a[lo] <= a[mid]) {                       // [lo, mid] is sorted
            if (a[lo] <= target && target < a[mid]) hi = mid - 1;
            else lo = mid + 1;
        } else {                                     // [mid, hi] is sorted
            if (a[mid] < target && target <= a[hi]) lo = mid + 1;
            else hi = mid - 1;
        }
    }
    return -1;
}

int search(const std::vector<int>& nums, int target) {
    int lo = 0, hi = (int)nums.size();          // invariant: answer in [lo, hi)
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;           // no overflow of lo + hi
        if (nums[mid] < target) lo = mid + 1;
        else hi = mid;
    }
    // lo = first index with nums[lo] >= target (lower_bound)
    return (lo < (int)nums.size() && nums[lo] == target) ? lo : -1;
}

double findMedianSortedArrays(const std::vector<int>& A, const std::vector<int>& B) {
    if (A.size() > B.size()) return findMedianSortedArrays(B, A);   // search the shorter
    const int NEG = std::numeric_limits<int>::min(), POS = std::numeric_limits<int>::max();
    int m = A.size(), n = B.size(), half = (m + n + 1) / 2;
    int lo = 0, hi = m;
    while (lo <= hi) {
        int i = lo + (hi - lo) / 2;      // i elements from A on the left side
        int j = half - i;                // j elements from B on the left side
        int aL = i > 0 ? A[i - 1] : NEG, aR = i < m ? A[i] : POS;
        int bL = j > 0 ? B[j - 1] : NEG, bR = j < n ? B[j] : POS;
        if (aL > bR) hi = i - 1;         // too many from A
        else if (bL > aR) lo = i + 1;    // too few from A
        else if ((m + n) % 2) return std::max(aL, bL);
        else return (std::max(aL, bL) + (double)std::min(aR, bR)) / 2.0;
    }
    return 0.0;                          // unreachable for sorted input
}

int findMin(const std::vector<int>& a) {
    int lo = 0, hi = (int)a.size() - 1;
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (a[mid] > a[hi]) lo = mid + 1;   // the drop is to the right of mid
        else hi = mid;                      // [mid, hi] sorted: min is at mid or left of it
    }
    return a[lo];
}

std::vector<int> findClosestElements(const std::vector<int>& a, int k, int x) {
    int lo = 0, hi = (int)a.size() - k;          // window start in [0, n - k]
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        // a[mid] leaves, a[mid + k] enters: move right only if it is strictly closer
        if (x - a[mid] > a[mid + k] - x) lo = mid + 1;
        else hi = mid;
    }
    return std::vector<int>(a.begin() + lo, a.begin() + lo + k);
}

bool searchMatrix(const std::vector<std::vector<int>>& M, int target) {
    int m = M.size(), n = M[0].size();
    int lo = 0, hi = m * n;                       // virtual sorted array [0, m*n)
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (M[mid / n][mid % n] < target) lo = mid + 1;
        else hi = mid;
    }
    return lo < m * n && M[lo / n][lo % n] == target;
}

bool searchMatrix(const std::vector<std::vector<int>>& M, int target) {
    if (M.empty() || M[0].empty()) return false;
    int r = 0, c = (int)M[0].size() - 1;          // start at the top-right corner
    while (r < (int)M.size() && c >= 0) {
        if (M[r][c] == target) return true;
        if (M[r][c] > target) --c;     // everything below in column c is even larger
        else ++r;                      // everything left in row r is even smaller
    }
    return false;
}

