std::vector<int> searchRange(const std::vector<int>& a, int target) {
    int l = firstIndex(a, target, false);                 // lower_bound
    if (l == (int)a.size() || a[l] != target) return {-1, -1};
    return {l, firstIndex(a, target, true) - 1};          // upper_bound - 1
}

int splitArray(const std::vector<int>& a, int k) {
    long long lo = *std::max_element(a.begin(), a.end());          // every element fits alone
    long long hi = std::accumulate(a.begin(), a.end(), 0LL);       // one part
    auto partsNeeded = [&](long long cap) {     // greedy: fill a part until the next won't fit
        int parts = 1;
        long long cur = 0;
        for (int x : a) {
            if (cur + x > cap) { ++parts; cur = 0; }
            cur += x;
        }
        return parts;
    };
    while (lo < hi) {
        long long mid = lo + (hi - lo) / 2;
        if (partsNeeded(mid) <= k) hi = mid;    // feasible: try a smaller max
        else lo = mid + 1;
    }
    return (int)lo;
}

