int shipWithinDays(const std::vector<int>& w, int days) {
    int lo = *std::max_element(w.begin(), w.end());     // the heaviest package must fit
    int hi = std::accumulate(w.begin(), w.end(), 0);    // everything in one day (<= 2.5e7)
    auto daysNeeded = [&](int cap) {
        int d = 1, cur = 0;
        for (int x : w) {
            if (cur + x > cap) { ++d; cur = 0; }        // start a new day
            cur += x;
        }
        return d;
    };
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (daysNeeded(mid) <= days) hi = mid;
        else lo = mid + 1;
    }
    return lo;
}

