int minDays(const std::vector<int>& bloom, int m, int k) {
    if ((long long)m * k > (long long)bloom.size()) return -1;   // m*k may overflow int
    auto [mn, mx] = std::minmax_element(bloom.begin(), bloom.end());
    int lo = *mn, hi = *mx;
    auto canMake = [&](int day) {
        int bouquets = 0, run = 0;
        for (int b : bloom) {
            if (b > day) run = 0;                       // a gap breaks adjacency
            else if (++run == k) { ++bouquets; run = 0; }
        }
        return bouquets >= m;
    };
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (canMake(mid)) hi = mid;
        else lo = mid + 1;
    }
    return lo;
}

