int leftMostColumnWithOne(BinaryMatrix& M) {
    std::vector<int> d = M.dimensions();
    int rows = d[0], cols = d[1];
    int r = 0, c = cols - 1, ans = -1;
    while (r < rows && c >= 0) {          // start at the top-right corner
        if (M.get(r, c) == 1) {
            ans = c;                      // best so far; look further left in this row
            --c;
        } else {
            ++r;                          // this row has no 1 at or left of c
        }
    }
    return ans;
}

def minimum_time(time, total_trips):
    lo, hi = 1, min(time) * total_trips     # the fastest bus alone is enough by hi
    while lo < hi:
        mid = (lo + hi) // 2
        trips = 0
        for t in time:
            trips += mid // t
            if trips >= total_trips:        # early exit (in C++ also prevents overflow)
                break
        if trips >= total_trips:
            hi = mid
        else:
            lo = mid + 1
    return lo

