int rowWithMaxOnes(const std::vector<std::vector<int>>& g) {
    if (g.empty()) return -1;
    int m = g[0].size();
    int col = m - 1, best = -1;
    for (int r = 0; r < (int)g.size() && col >= 0; ++r) {
        while (col >= 0 && g[r][col] == 1) {   // move left while we see 1s
            --col;
            best = r;                           // this row beats all previous ones
        }
    }
    return best;
}

