#include <vector>
#include <algorithm>

int countDistinctSorted(const std::vector<int>& a) {
    int n = a.size(), i = 0, count = 0;
    while (i < n) {
        ++count;
        int v = a[i];
        int step = 1, lo = i;                 // a[lo] == v
        while (i + step < n && a[i + step] == v) {   // gallop: 1, 2, 4, ...
            lo = i + step;
            step *= 2;
        }
        int hi = std::min(n, i + step);       // a[hi] != v (or hi == n)
        i = std::upper_bound(a.begin() + lo, a.begin() + hi, v) - a.begin();
    }
    return count;
}

int get(long long i);      // provided: 0 or 1

long long firstOne() {
    if (get(0) == 1) return 0;
    long long lo = 0, hi = 1;             // invariant: get(lo) == 0
    while (get(hi) == 0) {               // gallop until we see a 1
        lo = hi;
        hi *= 2;
    }
    // first 1 is in (lo, hi]
    while (hi - lo > 1) {
        long long mid = lo + (hi - lo) / 2;
        if (get(mid) == 1) hi = mid; else lo = mid;
    }
    return hi;
}
